    "solution": "class ListNode:\r\n\r\n    def __init__(self, key, val):\r\n        self.key = key\r\n        self.val = val\r\n        self.freq = 1\r\n        self.prev = None\r\n        self.next = None\r\n\r\nclass LinkedList:\r\n\r\n    def __init__(self):\r\n        self.left = ListNode(0, 0)\r\n        self.right = ListNode(0, 0)\r\n        self.left.next = self.right\r\n        self.right.prev = self.left\r\n        self.size = 0\r\n\r\n    def length(self):\r\n        return self.size\r\n\r\n    def pushRight(self, node):\r\n        prev = self.right.prev\r\n        prev.next = node\r\n        node.prev = prev\r\n        node.next = self.right\r\n        self.right.prev = node\r\n        self.size += 1\r\n\r\n    def pop(self, node):\r\n        prev, next = node.prev, node.next\r\n        prev.next = next\r\n        next.prev = prev\r\n        node.prev = None\r\n        node.next = None\r\n        self.size -= 1\r\n\r\n    def popLeft(self):\r\n        if self.length() == 0:\r\n            return None\r\n        node = self.left.next\r\n        self.pop(node)\r\n        return node\r\n\r\nclass LFUCache:\r\n\r\n    def __init__(self, capacity: int):\r\n        self.cap = capacity\r\n        self.lfuCnt = 0\r\n        self.nodeMap = {} # Map key -> node\r\n        # Map frequency -> linkedlist of nodes\r\n        self.listMap = defaultdict(LinkedList)\r\n\r\n    def counter(self, node):\r\n        cnt = node.freq\r\n        self.listMap[cnt].pop(node)\r\n\r\n        if cnt == self.lfuCnt and self.listMap[cnt].length() == 0:\r\n            self.lfuCnt += 1\r\n\r\n        node.freq += 1\r\n        self.listMap[node.freq].pushRight(node)\r\n\r\n\r\n    def get(self, key: int) -> int:\r\n        if key not in self.nodeMap:\r\n            return -1\r\n        node = self.nodeMap[key]\r\n        self.counter(node)\r\n        return node.val\r\n\r\n    def put(self, key: int, value: int) -> None:\r\n        if self.cap == 0:\r\n            return\r\n\r\n        if key in self.nodeMap:\r\n            node = self.nodeMap[key]\r\n            node.val = value\r\n            self.counter(node)\r\n            return\r\n\r\n        if len(self.nodeMap) == self.cap:\r\n            node = self.listMap[self.lfuCnt].popLeft()\r\n            self.nodeMap.pop(node.key)\r\n\r\n        node = ListNode(key, value)\r\n        self.nodeMap[key] = node\r\n        self.listMap[1].pushRight(node)\r\n        self.lfuCnt = 1",
